CUDA_SRC='\n#include <torch/extension.h>\n#include <ATen/cuda/CUDAContext.h>\n#include <cuda_runtime.h>\n#include <cstdint>\n\n__device__ __forceinline__ uint64_t affine_bf16x4(uint64_t word, uint32_t ss) {\n  uint32_t lo = (uint32_t)word, hi = (uint32_t)(word >> 32), a, b;\n  asm volatile("{ .reg .b32 nz; mov.b32 nz, 0x80008000; fma.rn.bf16x2 %0, %2, %4, nz; fma.rn.bf16x2 %1, %3, %4, nz; }"\n               : "=r"(a), "=r"(b) : "r"(lo), "r"(hi), "r"(ss));\n  return (uint64_t)a | ((uint64_t)b << 32);\n}\n__device__ __forceinline__ float bf16bits_to_f32(uint32_t bits16) { return __uint_as_float(bits16 << 16); }\ntemplate <int MODE>\n__device__ __forceinline__ float divide_exact(float x, float s, float r) {\n  if constexpr (MODE == 6) { float q = __fmul_rn(x, r); float res = __fmaf_rn(-q, s, x); return __fmaf_rn(res, r, q); }\n  else { return __fdiv_rn(x, s); }\n}\n__device__ __forceinline__ uint32_t cvt_rni_sat_s8(float v) { int r; asm("cvt.rni.sat.s8.f32 %0, %1;" : "=r"(r) : "f"(v)); return (uint32_t)r & 0xffu; }\n\ntemplate <int MODE>\n__device__ __forceinline__ uint32_t finish_vector(uint64_t code, uint32_t sbits, float s, float r) {\n  uint64_t w = affine_bf16x4(code, sbits * 0x10001u);\n  float q0 = bf16bits_to_f32((uint32_t)(w & 0xffffu));\n  float q1 = bf16bits_to_f32((uint32_t)((w >> 16) & 0xffffu));\n  float q2 = bf16bits_to_f32((uint32_t)((w >> 32) & 0xffffu));\n  float q3 = bf16bits_to_f32((uint32_t)((w >> 48) & 0xffffu));\n  uint32_t b0 = cvt_rni_sat_s8(divide_exact<MODE>(q0, s, r));\n  uint32_t b1 = cvt_rni_sat_s8(divide_exact<MODE>(q1, s, r));\n  uint32_t b2 = cvt_rni_sat_s8(divide_exact<MODE>(q2, s, r));\n  uint32_t b3 = cvt_rni_sat_s8(divide_exact<MODE>(q3, s, r));\n  return b0 | (b1 << 8) | (b2 << 16) | (b3 << 24);\n}\n\n\n#include <c10/cuda/CUDAException.h>\n\n\n__device__ __forceinline__ float normal_rcp_rn(float s) {\n float r; asm("rcp.rn.ftz.f32 %0, %1;" : "=f"(r) : "f"(s)); return r;\n}\n\ntemplate<int BITS,int MODE,int K>\n__device__ __forceinline__ uint4 decode_four(int v,const uint32_t* p,const uint64_t* cb,const uint16_t* sc,const float* sw) {\n  constexpr int TOTAL=2359296,WORDS=TOTAL*BITS/32;\n  const int bit=v*BITS,wi=bit>>5,off=bit&31;\n  uint32_t low=p[wi],high=0;\n  if(wi+1<WORDS)high=p[wi+1];\n  uint64_t code[4];\n  if constexpr(BITS<=8){\n    uint32_t aligned=__funnelshift_r(low,high,off);\n    #pragma unroll\n    for(int i=0;i<4;++i)code[i]=cb[(aligned>>(i*BITS))&((1u<<BITS)-1)];\n  }else{\n    uint64_t window=(uint64_t)low|((uint64_t)high<<32);\n    #pragma unroll\n    for(int i=0;i<4;++i)code[i]=cb[(window>>(off+i*BITS))&((1u<<BITS)-1)];\n  }\n  uint32_t sbits=sc[v/16];\n  float s=sw[v/(K/4)],reciprocal=0;\n  if constexpr(MODE==6) reciprocal=normal_rcp_rn(s);\n  uint4 result;\n  result.x=finish_vector<MODE>(code[0],sbits,s,reciprocal);\n  result.y=finish_vector<MODE>(code[1],sbits,s,reciprocal);\n  result.z=finish_vector<MODE>(code[2],sbits,s,reciprocal);\n  result.w=finish_vector<MODE>(code[3],sbits,s,reciprocal);\n  return result;\n}\ntemplate<int B0,int M0,int B1,int M1>\n__global__ void __launch_bounds__(128) decode_grouped_ff_vec4cta128_cuda_r1(\n const uint32_t* p0,const uint64_t* c0,const uint16_t* s0,const float* w0,uint32_t* o0,\n const uint32_t* p1,const uint64_t* c1,const uint16_t* s1,const float* w1,uint32_t* o1) {\n constexpr int TILE=1024,TILES=2304;\n int block=blockIdx.x;\n if(block<TILES) {\n  #pragma unroll\n  for(int slice=0;slice<2;slice++){\n   int v=block*TILE+threadIdx.x*4+slice*512;\n   reinterpret_cast<uint4*>(o0)[v/4]=decode_four<B0,M0,1536>(v,p0,c0,s0,w0);\n  }\n } else {\n  block-=TILES;\n  #pragma unroll\n  for(int slice=0;slice<2;slice++){\n   int v=block*TILE+threadIdx.x*4+slice*512;\n   reinterpret_cast<uint4*>(o1)[v/4]=decode_four<B1,M1,6144>(v,p1,c1,s1,w1);\n  }\n }\n}\ntemplate<int B0,int M0,int B1,int M1>\nvoid launch_pair(std::vector<torch::Tensor>& x) {\n decode_grouped_ff_vec4cta128_cuda_r1<B0,M0,B1,M1><<<4608,128,0,at::cuda::getCurrentCUDAStream()>>>(\n (const uint32_t*)x[0].data_ptr(),(const uint64_t*)x[1].data_ptr(),(const uint16_t*)x[2].data_ptr(),(const float*)x[5].data_ptr(),(uint32_t*)x[4].data_ptr(),\n (const uint32_t*)x[6].data_ptr(),(const uint64_t*)x[7].data_ptr(),(const uint16_t*)x[8].data_ptr(),(const float*)x[11].data_ptr(),(uint32_t*)x[10].data_ptr());\n}\ntemplate<int B0,int M0>\nvoid choose_down(std::vector<torch::Tensor>& x,int b1,int m1) {\n #define DOWN_CASE(B) case B: if(m1==6) launch_pair<B0,M0,B,6>(x);else launch_pair<B0,M0,B,0>(x);break;\n switch(b1){DOWN_CASE(5) DOWN_CASE(6) DOWN_CASE(7) default:TORCH_CHECK(false,"bits1");}\n #undef DOWN_CASE\n}\nvoid decode_pair_vec4cta128_r1(std::vector<torch::Tensor> x,int64_t b0,int64_t m0,int64_t b1,int64_t m1) {\n TORCH_CHECK(x.size()==12 && (m0==0||m0==6)&&(m1==0||m1==6),"arguments");\n for(auto& t:x)TORCH_CHECK(t.is_cuda()&&t.is_contiguous()&&t.device()==x[0].device(),"layout/device");\n TORCH_CHECK(x[4].scalar_type()==torch::kInt8 && x[10].scalar_type()==torch::kInt8,"output dtype");\n TORCH_CHECK(x[4].sizes()==at::IntArrayRef({6144,1536})&&x[10].sizes()==at::IntArrayRef({1536,6144}),"shape");\n TORCH_CHECK(x[1].scalar_type()==torch::kBFloat16&&x[7].scalar_type()==torch::kBFloat16,"codebook dtype");\n TORCH_CHECK(x[2].scalar_type()==torch::kBFloat16&&x[8].scalar_type()==torch::kBFloat16,"scale dtype");\n TORCH_CHECK(x[5].scalar_type()==torch::kFloat32&&x[11].scalar_type()==torch::kFloat32,"row scale dtype");\n #define UP_CASE(B) case B: if(m0==6)choose_down<B,6>(x,b1,m1);else choose_down<B,0>(x,b1,m1);break;\n switch(b0){UP_CASE(5) UP_CASE(6) UP_CASE(7) default:TORCH_CHECK(false,"bits0");}\n #undef UP_CASE\n C10_CUDA_KERNEL_LAUNCH_CHECK();\n}\n\n__global__ void reciprocal_gate_kernel_r1(const float* s,float* a,float* b,int n){int i=blockIdx.x*256+threadIdx.x;if(i<n){a[i]=__frcp_rn(s[i]);b[i]=normal_rcp_rn(s[i]);}}\nvoid reciprocal_pair_r1(torch::Tensor s,torch::Tensor a,torch::Tensor b){\n TORCH_CHECK(s.is_cuda()&&s.is_contiguous()&&s.scalar_type()==torch::kFloat32,"scales");\n TORCH_CHECK(a.is_cuda()&&b.is_cuda()&&a.is_contiguous()&&b.is_contiguous()&&a.device()==s.device()&&b.device()==s.device()&&a.scalar_type()==torch::kFloat32&&b.scalar_type()==torch::kFloat32&&a.numel()==s.numel()&&b.numel()==s.numel(),"outputs");\n reciprocal_gate_kernel_r1<<<(s.numel()+255)/256,256,0,at::cuda::getCurrentCUDAStream()>>>(s.data_ptr<float>(),a.data_ptr<float>(),b.data_ptr<float>(),s.numel());C10_CUDA_KERNEL_LAUNCH_CHECK();\n}\n'
CPP_SRC='#include <torch/extension.h>\nvoid decode_pair_vec4cta128_r1(std::vector<torch::Tensor>,int64_t,int64_t,int64_t,int64_t);\nvoid reciprocal_pair_r1(torch::Tensor,torch::Tensor,torch::Tensor);'
_ext=None
def ext():
 global _ext
 if _ext is None:
  bd='@LOCAL_RUNTIME@/codex_ffdecode_vec4cta128_build_r1';os.makedirs(bd,exist_ok=True)
  _ext=load_inline('codex_ffdecode_vec4cta128_r1',cpp_sources=[CPP_SRC],cuda_sources=[CUDA_SRC],functions=['decode_pair_vec4cta128_r1','reciprocal_pair_r1'],extra_cuda_cflags=['-O3','-std=c++17','-gencode=arch=compute_89,code=sm_89','--fmad=false'],build_directory=bd,verbose=True)
