def validate_reciprocal(scales):
 import torch
 assert scales.dtype==torch.float32 and scales.is_cuda and scales.is_contiguous()
 assert bool(torch.all(torch.isfinite(scales)&(scales>=2.0**-126)&(scales<=2.0**126)).item()),'ScaleOutsideNormalReciprocalRange'
 a=torch.empty_like(scales);b=torch.empty_like(scales)
 ext().reciprocal_pair_r1(scales,a,b)
 assert torch.equal(a.view(torch.int32),b.view(torch.int32)),'ReciprocalRNBitsMismatch'
 assert bool(torch.all(torch.isfinite(b)&(b>=2.0**-126)).item()),'ReciprocalNotNormal'
 return dict(count=scales.numel(),minimum=float(scales.min().item()),maximum=float(scales.max().item()),reciprocal_bits_exact=True)
